// 1. Obtenemos el texto crudo de Gemini
const rawText = $node["Analyze an image"].json.content.parts[0].text;

// 2. Limpiamos las etiquetas ```json y ``` que estorban
const cleanText = rawText.replace(/```json|```/g, "").trim();

// 3. Lo convertimos en un objeto JSON real para n8n
return JSON.parse(cleanText);

